// Genealogiq APP — PWA service worker: Tier 1 (installability + branding +
// offline fallback) and Tier 2 (web push notifications).
//
// Hand-written, not generated by a build plugin: this app's Next.js config
// defaults to Turbopack (see next dev/build with no --webpack flag), and the
// current PWA tooling (next-pwa, @serwist/next's webpack plugin) doesn't run
// under Turbopack. A static file avoids that mismatch entirely.
//
// Scope is deliberately narrow:
//  - Precache a fixed list of visitor-agnostic static assets (fonts, brand
//    images, manifest icons) plus the offline fallback page.
//  - On navigation, always hit the network first (with navigation preload);
//    only fall back to the cached offline page when the network fetch fails.
//  - Cache /_next/static/* build assets on use (content-hashed, immutable),
//    so the offline page renders with its real CSS.
//  - Everything else (protected pages, Server Actions, /api/*, per-viewer
//    profile pages) is never intercepted — requests fall through to the
//    browser's normal network handling untouched.
const STATIC_CACHE = "giq-static-v2"
const NEXT_ASSET_CACHE = "giq-next-assets-v1"
const ALLOWED_CACHES = [STATIC_CACHE, NEXT_ASSET_CACHE]

const OFFLINE_URL = "/offline"
const NEXT_ASSET_MAX_ENTRIES = 80
const OFFLINE_REFRESH_INTERVAL_MS = 60 * 60 * 1000 // refresh the snapshot at most hourly

// Install fails (and self-retries on the next visit) if these fail — they are
// the two documents installability and the offline fallback depend on.
const CRITICAL_URLS = [OFFLINE_URL, "/manifest.webmanifest"]

// Nice-to-have branding assets: cached best-effort so a renamed logo or font
// can never brick installability.
const OPTIONAL_URLS = [
  "/icons/icon-192.png",
  "/icons/icon-192-maskable.png",
  "/icons/icon-512.png",
  "/icons/icon-512-maskable.png",
  "/icons/apple-touch-icon.png",
  "/logo-dark.png",
  "/logo-light.png",
  "/tree-dark.png",
  "/tree-light.png",
  "/fonts/inter/inter-latin-wght-normal.woff2",
  "/fonts/inter/inter-latin-wght-italic.woff2",
]

const PRECACHE_URLS = [...CRITICAL_URLS, ...OPTIONAL_URLS]

// Last-resort offline document, used only if the cached /offline snapshot has
// been evicted. Self-contained: no external CSS/JS/fonts.
const FALLBACK_HTML = `<!doctype html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="color-scheme" content="light dark">
<title>Genealogiq</title>
<style>
  body { font-family: system-ui, sans-serif; display: flex; min-height: 100vh;
         margin: 0; align-items: center; justify-content: center; text-align: center; }
  main { padding: 1rem; }
  h1 { font-size: 1.5rem; }
  p { opacity: 0.7; }
</style>
</head>
<body>
<main>
  <h1>Genealogiq</h1>
  <p>You're offline. / Você está offline. / Estás sin conexión.</p>
</main>
</body>
</html>`

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(STATIC_CACHE)
      // { cache: "reload" } bypasses the HTTP cache so the precache always
      // holds fresh copies, not whatever the browser had lying around.
      await cache.addAll(CRITICAL_URLS.map((url) => new Request(url, { cache: "reload" })))
      await Promise.allSettled(
        OPTIONAL_URLS.map((url) => cache.add(new Request(url, { cache: "reload" })))
      )
      // skipWaiting is safe here: navigations are network-first, so an
      // instant takeover can never serve pages from a mixed build.
      await self.skipWaiting()
    })()
  )
})

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      // Navigation preload lets the network request start in parallel with
      // SW boot, removing the SW-startup latency from every navigation.
      if (self.registration.navigationPreload) {
        await self.registration.navigationPreload.enable()
      }
      const names = await caches.keys()
      await Promise.all(
        names.filter((name) => !ALLOWED_CACHES.includes(name)).map((name) => caches.delete(name))
      )
      await self.clients.claim()
    })()
  )
})

// The /offline snapshot is precached once at install, but sw.js bytes rarely
// change, so without a refresh it would go stale across deploys (referencing
// purged /_next/static chunks). After a successful online navigation, refresh
// it at most hourly. The fetch is credentialed on purpose: the locale cookie
// keeps the snapshot in the visitor's language, and the page renders no
// user-specific content beyond the generic feedback links in the footer.
let lastOfflineRefresh = 0

function refreshOfflineSnapshot() {
  fetch(new Request(OFFLINE_URL, { cache: "reload" }))
    .then(async (response) => {
      if (response.ok && !response.redirected) {
        const cache = await caches.open(STATIC_CACHE)
        await cache.put(OFFLINE_URL, response)
      }
    })
    .catch(() => {
      // Offline or flaky — retry on a later navigation.
      lastOfflineRefresh = 0
    })
}

function maybeRefreshOfflineSnapshot() {
  const now = Date.now()
  if (now - lastOfflineRefresh < OFFLINE_REFRESH_INTERVAL_MS) return
  lastOfflineRefresh = now
  refreshOfflineSnapshot()
}

// The language switcher posts { type: "locale-changed" } after rewriting the
// locale cookie, so the snapshot doesn't stay in the previous language until
// the hourly throttle expires.
self.addEventListener("message", (event) => {
  if (event.data && event.data.type === "locale-changed") {
    lastOfflineRefresh = Date.now()
    refreshOfflineSnapshot()
  }
})

// Precached assets live at fixed URLs (the manifest can't be renamed, logos
// and fonts are edited in place), so pure cache-first would pin the copies
// captured at install time until sw.js itself changes. Revalidate each one in
// the background at most once per SW lifetime; ETag/Last-Modified make the
// re-fetch a cheap 304 when nothing changed.
const revalidatedThisLifetime = new Set()

function maybeRevalidatePrecached(pathname) {
  if (revalidatedThisLifetime.has(pathname)) return
  revalidatedThisLifetime.add(pathname)
  fetch(new Request(pathname, { cache: "no-cache" }))
    .then(async (response) => {
      if (response.ok && !response.redirected) {
        const cache = await caches.open(STATIC_CACHE)
        await cache.put(pathname, response)
      }
    })
    .catch(() => {
      revalidatedThisLifetime.delete(pathname)
    })
}

// Trim a cache to at most maxEntries, deleting oldest-inserted first. Good
// enough as FIFO: /_next/static files are content-hashed, so old-build assets
// simply age out.
async function trimCache(cacheName, maxEntries) {
  const cache = await caches.open(cacheName)
  const keys = await cache.keys()
  for (const key of keys.slice(0, Math.max(0, keys.length - maxEntries))) {
    await cache.delete(key)
  }
}

// ─── Web Push (Tier 2) ───────────────────────────────────────────────────────
// Payloads are built server-side (src/lib/push.ts → src/lib/push-payload.ts):
// { title, body, url, tag }, already in the recipient's language. The
// try/catch fallback covers DevTools' payload-less "Push" test button.

self.addEventListener("push", (event) => {
  let data = {}
  try {
    data = event.data ? event.data.json() : {}
  } catch {
    // Non-JSON test push — show the generic fallback.
  }
  const title = data.title || "Genealogiq"
  event.waitUntil(
    self.registration.showNotification(title, {
      body: data.body || "",
      icon: "/icons/icon-192.png",
      badge: "/icons/icon-192.png",
      tag: data.tag || undefined,
      data: { url: data.url || "/messages" },
    })
  )
})

self.addEventListener("notificationclick", (event) => {
  event.notification.close()
  const url = new URL(event.notification.data?.url || "/messages", self.location.origin).href
  event.waitUntil(
    (async () => {
      const windowClients = await self.clients.matchAll({
        type: "window",
        includeUncontrolled: true,
      })
      const exact = windowClients.find((client) => client.url === url)
      if (exact) return exact.focus()
      const openClient = windowClients.find((client) => "navigate" in client)
      if (openClient) {
        await openClient.focus()
        return openClient.navigate(url)
      }
      return self.clients.openWindow(url)
    })()
  )
})

self.addEventListener("fetch", (event) => {
  const { request } = event

  // 1. Navigations: network-first (preload when available), offline fallback.
  //    GET only — a POST navigation must never be answered with a cached page.
  if (request.mode === "navigate" && request.method === "GET") {
    event.respondWith(
      (async () => {
        try {
          const preload = await event.preloadResponse
          const response = preload || (await fetch(request))
          maybeRefreshOfflineSnapshot()
          return response
        } catch {
          const cached = await caches.match(OFFLINE_URL)
          return (
            cached ||
            new Response(FALLBACK_HTML, {
              status: 503,
              headers: { "Content-Type": "text/html; charset=utf-8" },
            })
          )
        }
      })()
    )
    return
  }

  if (request.method !== "GET") return
  const url = new URL(request.url)
  if (url.origin !== self.location.origin) return

  // 2. Next build assets: cache-first. Content-hashed filenames make these
  //    immutable, so a cached copy is always correct; caching them is what
  //    lets the offline page render with its real stylesheet.
  if (url.pathname.startsWith("/_next/static/")) {
    event.respondWith(
      (async () => {
        const cached = await caches.match(request)
        if (cached) return cached
        const response = await fetch(request)
        if (response.ok) {
          const cache = await caches.open(NEXT_ASSET_CACHE)
          await cache.put(request, response.clone())
          trimCache(NEXT_ASSET_CACHE, NEXT_ASSET_MAX_ENTRIES)
        }
        return response
      })()
    )
    return
  }

  // 3. Precached static assets: cache-first with network fill, plus a
  //    once-per-lifetime background revalidation (fixed URLs go stale
  //    otherwise — see maybeRevalidatePrecached).
  if (PRECACHE_URLS.includes(url.pathname)) {
    event.respondWith(
      (async () => {
        const cached = await caches.match(request)
        if (cached) {
          maybeRevalidatePrecached(url.pathname)
          return cached
        }
        const response = await fetch(request)
        if (response.ok) {
          const cache = await caches.open(STATIC_CACHE)
          await cache.put(request, response.clone())
        }
        return response
      })()
    )
  }

  // Anything else (protected pages, Server Actions, /api/*, per-viewer
  // profile pages) is left alone — no respondWith, no interception.
})
